import hashlib, itertools

def keystream(key: bytes):
    for counter in itertools.count():
        yield from hashlib.sha256(key + counter.to_bytes(8, "big")).digest()

def xor_cipher(key, data):
    return bytes(b ^ k for b, k in zip(data, keystream(key)))

secret = b"meet at the library at noon"
ciphertext = xor_cipher(b"shared key", secret)
print(ciphertext.hex())
print(xor_cipher(b"shared key", ciphertext))            # the same key decrypts
print(xor_cipher(b"wrong key!!", ciphertext))           # a wrong key gives noise
